definition.script:
pipeline {
    agent any
    stages {
        stage('Confirm Authenticated HPDS Is Public') {
            when {
                expression { env.ENABLE_EXPLORE_WITHOUT_LOGIN.toBoolean() && !env.CONFIRM_AUTH_HPDS_PUBLIC.toBoolean() }
            }
            steps {
                error('CONFIRM_AUTH_HPDS_PUBLIC must be true when ENABLE_EXPLORE_WITHOUT_LOGIN=true.')
            }
        }

        stage('Configure Anonymous Access') {
            steps {
                script {
                    def result = build job: 'Enable Explore Without Login', parameters: [
                        [$class: 'BooleanParameterValue', name: 'ENABLE_EXPLORE_WITHOUT_LOGIN', value: env.ENABLE_EXPLORE_WITHOUT_LOGIN.toBoolean()],
                        [$class: 'BooleanParameterValue', name: 'CONFIRM_AUTH_HPDS_PUBLIC', value: env.CONFIRM_AUTH_HPDS_PUBLIC.toBoolean()]
                    ]
                }
            }
        }

        stage('Rebuild Frontend') {
            steps {
                script {
                    def result = build job: 'PIC-SURE Frontend Build', parameters: [
                        [$class: 'StringParameterValue', name: 'pipeline_build_id', value: 'MANUAL_RUN'],
                        [$class: 'StringParameterValue', name: 'git_hash', value: env.FRONTEND_GIT_HASH]
                    ]
                }
            }
        }

        stage('Deploy') {
            steps {
                script {
                    def result = build job: 'Start PIC-SURE'
                }
            }
        }
    }
}
